35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    /**
82	     * Whether this owner was one of a bulk signup for its registration day (more than
83	     * 80 owners created for that day). Derived at response time, never persisted.
84	     */
85	    @Transient
86	    private Boolean bulkSignupWarning;
87	
88	    /**
89	     * The number of owners sharing this owner's household (the same householdId),
90	     * counting this owner. Derived at response time from the persisted householdId,
91	     * never persisted. Drives the 'GOLD' membership tier (3 or more members).
92	     */
93	    @Transient
94	    private Integer householdSize;
95	
96	    /**
97	     * Whether this owner is a soft-match of an existing (other) owner — sharing that
98	     * owner's lastName and postcode but carrying a different telephone (so it is not a
99	     * hard duplicate). Derived at response time, never persisted.
100	     */
101	    @Transient
102	    private Boolean possibleDuplicate;
103	
104	    /**
105	     * The id of the existing owner this owner soft-matches (see {@link #possibleDuplicate}),
106	     * or null when it soft-matches none. Derived at response time, never persisted.
107	     */
108	    @Transient
109	    private Integer possibleDuplicateOf;
110	
111	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
112	    private Set<Pet> pets;
113	
114	    public String getTitle() {
115	        return this.title;
116	    }
117	
118	    public void setTitle(String title) {
119	        this.title = title;
120	    }
121	
122	    public String getAddress() {
123	        return this.address;
124	    }
125	
126	    public void setAddress(String address) {
127	        this.address = address;
128	    }
129	
130	    public String getAddressLine1() {
131	        return this.addressLine1;
132	    }
133	
134	    public void setAddressLine1(String addressLine1) {
135	        this.addressLine1 = addressLine1;
136	    }
137	
138	    public String getAddressLine2() {
139	        return this.addressLine2;
140	    }
141	
142	    public void setAddressLine2(String addressLine2) {
143	        this.addressLine2 = addressLine2;
144	    }
145	
146	    public String getCity() {
147	        return this.city;
148	    }
149	
150	    public void setCity(String city) {
151	        this.city = city;
152	    }
153	
154	    public String getTelephone() {
155	        return this.telephone;
156	    }
157	
158	    public void setTelephone(String telephone) {
159	        this.telephone = telephone;
160	    }
161	
162	    public String getEmail() {
163	        return this.email;
164	    }
165	
166	    public void setEmail(String email) {
167	        this.email = email;
168	    }
169	
170	    public String getPostcode() {
171	        return this.postcode;
172	    }
173	
174	    public void setPostcode(String postcode) {
175	        this.postcode = postcode;
176	    }
177	
178	    public LocalDate getRegistrationDate() {
179	        return this.registrationDate;
180	    }
181	
182	    public void setRegistrationDate(LocalDate registrationDate) {
183	        this.registrationDate = registrationDate;
184	    }
185	
186	    public LocalDate getBirthDate() {
187	        return this.birthDate;
188	    }
189	
190	    public void setBirthDate(LocalDate birthDate) {
191	        this.birthDate = birthDate;
192	    }
193	
194	    public String getCustomerCode() {
195	        return this.customerCode;
196	    }
197	
198	    public void setCustomerCode(String customerCode) {
199	        this.customerCode = customerCode;
200	    }
201	
202	    public String getHouseholdId() {
203	        return this.householdId;
204	    }
205	
206	    public void setHouseholdId(String householdId) {
207	        this.householdId = householdId;
208	    }
209	
210	    public Integer getNamesakeCount() {
211	        return this.namesakeCount;
212	    }
213	
214	    public void setNamesakeCount(Integer namesakeCount) {
215	        this.namesakeCount = namesakeCount;
216	    }
217	
218	    public Boolean getBulkSignupWarning() {
219	        return this.bulkSignupWarning;
220	    }
221	
222	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
223	        this.bulkSignupWarning = bulkSignupWarning;
224	    }
225	
226	    public Integer getHouseholdSize() {
227	        return this.householdSize;
228	    }
229	
230	    public void setHouseholdSize(Integer householdSize) {
231	        this.householdSize = householdSize;
232	    }
233	
234	    public Boolean getPossibleDuplicate() {
235	        return this.possibleDuplicate;
236	    }
237	
238	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
239	        this.possibleDuplicate = possibleDuplicate;
240	    }
241	
242	    public Integer getPossibleDuplicateOf() {
243	        return this.possibleDuplicateOf;
244	    }
245	
246	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
247	        this.possibleDuplicateOf = possibleDuplicateOf;
248	    }
249	
250	    protected Set<Pet> getPetsInternal() {
251	        if (this.pets == null) {
252	            this.pets = new HashSet<>();
253	        }
254	        return this.pets;
255	    }
256	
257	    protected void setPetsInternal(Set<Pet> pets) {
258	        this.pets = pets;
259	    }
260	
261	    public List<Pet> getPets() {
262	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
263	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
264	        return Collections.unmodifiableList(sortedPets);
265	    }
266	
267	    public void setPets(List<Pet> pets) {
268	        this.pets = new HashSet<>(pets);
269	    }
270	
271	    public void addPet(Pet pet) {
272	        getPetsInternal().add(pet);
273	        pet.setOwner(this);
274	    }
275	
276	    /**
277	     * Return the Pet with the given name, or null if none found for this Owner.
278	     *
279	     * @param name to test
280	     * @return true if pet name is already in use
281	     */
282	    public Pet getPet(String name) {
283	        return getPet(name, false);
284	    }
285	
286	    /**
287	     * Return the Pet with the given name, or null if none found for this Owner.
288	     *
289	     * @param name to test
290	     * @return true if pet name is already in use
291	     */
292	    public Pet getPet(String name, boolean ignoreNew) {
293	        name = name.toLowerCase();
294	        for (Pet pet : getPetsInternal()) {
295	            if (!ignoreNew || !pet.isNew()) {
296	                String compName = pet.getName();
297	                compName = compName.toLowerCase();
298	                if (compName.equals(name)) {
299	                    return pet;
300	                }
301	            }
302	        }
303	        return null;
304	    }
305	
306	    public Pet getPet(Integer petId) {
307	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
308	    }
309	
310	    @Override
311	    public String toString() {
312	        return new ToStringCreator(this)
313	
314	            .append("id", this.getId())
315	            .append("new", this.isNew())
316	            .append("lastName", this.getLastName())
317	            .append("firstName", this.getFirstName())
318	            .append("address", this.address)
319	            .append("city", this.city)
320	            .append("telephone", this.telephone)
321	            .toString();
322	    }
323	}
