11	
12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
15	        Owner owner = ownerMapper.toOwner(request);
16	        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
17	        owner.setRegistrationDate(BusinessDays.adjust(effective));
18	        built.set(owner);
19	    }
20	}
