13	
14	public class ListOwners {
15	
16	    public void service(@RequestParam(name = "lastName", required = false) String lastName,
17	            OwnerRepository ownerRepository, OwnerMapper ownerMapper,
18	            ObjectResponse<ResponseEntity<List<OwnerDto>>> response) {
19	        Collection<Owner> owners = lastName != null
20	                ? ownerRepository.findByLastName(lastName)
21	                : ownerRepository.findAll();
22	        if (owners.isEmpty()) {
23	            response.send(ResponseEntity.notFound().build());
24	            return;
25	        }
26	        response.send(ResponseEntity.ok(ownerMapper.toOwnerDtoCollection(owners)));
27	    }
28	}
